const HTML = "<!doctype html>\n<html lang=\"uk\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\">\n<title>WWG QA Team</title>\n<style>\n*{box-sizing:border-box}\nbody{margin:0;background:#efe2b5;color:#111;font-family:Arial,Inter,sans-serif}\nbutton,input,select{font:inherit}button{cursor:pointer}a{text-decoration:none;color:inherit}\n.shell{width:min(1200px,calc(100% - 28px));margin:0 auto}\n.top{background:#111116;color:white;padding:18px 0;position:sticky;top:0;z-index:10;border-bottom:1px solid rgba(255,255,255,.1)}\n.topin{display:flex;align-items:center;justify-content:space-between;gap:16px}\n.brand{display:flex;align-items:center;gap:12px;font-weight:900}.brand img{width:58px;height:58px;object-fit:contain;background:white;border-radius:12px}\n.nav{display:flex;gap:10px;flex-wrap:wrap}.nav a{color:rgba(255,255,255,.75);padding:8px 10px;border-radius:999px}.nav a:hover{background:rgba(255,255,255,.08);color:white}\n.hero{display:grid;grid-template-columns:1.05fr .95fr;gap:24px;padding:44px 0;align-items:center}\n.hero h1{margin:0;font-size:clamp(38px,6vw,72px);letter-spacing:-.07em;line-height:.92;color:#111}\n.hero p{font-size:18px;line-height:1.6;color:#5d5145}\n.card{background:rgba(255,255,255,.88);border:1px solid rgba(0,0,0,.1);border-radius:26px;padding:18px;box-shadow:0 18px 55px rgba(60,40,20,.12)}\n.visual{display:grid;gap:12px}.visual img{width:100%;object-fit:contain;border-radius:20px;background:#fff}.visual .mascot{background:#050505}\n.btn{min-height:40px;border:0;border-radius:12px;padding:10px 14px;font-weight:900;display:inline-flex;align-items:center;justify-content:center;gap:8px}\n.btn.blue{background:#16c9e8;color:#061317}.btn.red{background:#e31b23;color:#fff}.btn.light{background:#fff;color:#111;border:1px solid rgba(0,0,0,.14)}.btn.dark{background:#111;color:#fff}\n.section{margin:20px 0}.section h2{font-size:clamp(26px,4vw,44px);letter-spacing:-.055em;margin:0 0 12px}\n.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}\n.redirect-card{background:#fff;border:1px solid rgba(0,0,0,.12);border-radius:18px;padding:14px;display:grid;grid-template-columns:170px 1fr auto;gap:12px;align-items:center}\n.title{font-weight:900}.ok{color:#12a150}.link{color:#075985;overflow-wrap:anywhere;font-size:14px}.actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}\ninput,select{width:100%;min-height:42px;border:1px solid #d6d6df;border-radius:12px;padding:10px 12px;background:#fff;color:#111;outline:none}\n.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.row>*{flex:1}.row .btn{flex:0 0 auto}\n.log{margin-top:10px;background:#111827;color:#d1d5db;border-radius:14px;padding:12px;font-family:monospace;white-space:pre-wrap;font-size:13px}\n.pay-widget{background:#f5f7fa;border:1px solid #dde3ea;border-radius:10px;padding:16px;color:#1f2937}\n.pay-controls{display:flex;align-items:center;justify-content:center;gap:18px;flex-wrap:wrap;padding-bottom:14px;border-bottom:1px solid #dde3ea;margin-bottom:18px;font-size:14px;color:#475569}\n.pay-control{display:inline-flex;align-items:center;gap:6px;white-space:nowrap}\n.pay-select,.pay-small{min-height:32px;border:1px solid #cbd5e1;border-radius:7px;background:#fff;color:#111;padding:5px 8px;width:auto}\n.pay-small{width:46px;text-align:center}\n.pay-toggle{width:36px;height:20px;border-radius:999px;background:#dbe3ec;position:relative;display:inline-block}\n.pay-toggle:after{content:\"\";position:absolute;width:18px;height:18px;border-radius:50%;background:#fff;top:1px;left:1px;box-shadow:0 1px 4px rgba(0,0,0,.25)}\n.pay-buttons{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}\n.pay-button{height:44px;border:0;border-radius:5px;font-weight:900;display:flex;align-items:center;justify-content:center;gap:8px;color:#fff;transition:.14s ease}\n.pay-button:hover{transform:translateY(-1px);filter:brightness(1.02)}\n.pay-link{background:#00d66b;color:#061b10}.pay-gpay{background:#050505;color:#fff}.pay-klarna{background:#111;color:#fff}.pay-amazon{background:#ffd31a;color:#111}.pay-phonepe{background:#6739b7;color:#fff}.pay-paytm{background:#00baf2;color:#002e6e}.pay-playid{background:#222;color:#fff}.pay-kbc{background:#004b8d;color:#fff}\n.pay-url-row{margin-top:14px;display:grid;grid-template-columns:1fr auto;gap:8px}\n.notice{margin-top:12px;background:#fff3cd;color:#6f4e00;border:1px solid #ffe08a;border-radius:14px;padding:12px;line-height:1.5}\n.qrbox{min-height:270px;display:grid;place-items:center;text-align:center;border:1px dashed rgba(0,0,0,.2);border-radius:18px;background:rgba(255,255,255,.65);padding:16px}.qrbox img{width:220px;height:220px;background:#fff;padding:8px;border-radius:12px}\n.preview{width:100%;max-height:260px;object-fit:contain;margin-top:12px;display:none;background:#fff;border-radius:14px;padding:8px}\n.chat{height:240px;background:#fff;border:1px solid rgba(0,0,0,.12);border-radius:16px;padding:12px;overflow:auto;display:grid;align-content:start;gap:8px}.msg{background:#e5e7eb;padding:9px 11px;border-radius:14px;max-width:84%}.msg.user{justify-self:end;background:#a7f3d0}\n.modal{position:fixed;inset:0;background:rgba(0,0,0,.72);display:none;place-items:center;padding:16px;z-index:20}.modal.active{display:grid}.modalbox{width:min(520px,100%);background:#fff;border-radius:20px;padding:20px;position:relative}.close{position:absolute;top:10px;right:10px;border:0;border-radius:50%;width:34px;height:34px;background:#eee;font-size:22px}\n@media(max-width:850px){.hero,.grid,.grid3{grid-template-columns:1fr}.redirect-card{grid-template-columns:1fr}.actions{justify-content:flex-start}.pay-buttons,.pay-url-row{grid-template-columns:1fr}.nav{display:none}}\n</style>\n</head>\n<body>\n<header class=\"top\"><div class=\"shell topin\"><div class=\"brand\"><img src=\"data:image/png;base64,\" alt=\"WWG QA Team\"><span>WWG QA Team</span></div><nav class=\"nav\"><a href=\"#redirects\">Редіректи</a><a href=\"#pay\">Payment</a><a href=\"#qr\">QR</a><a href=\"#tools\">Tools</a></nav></div></header>\n<main class=\"shell\">\n<section class=\"hero\">\n<div><h1>QA dashboard без зайвого шуму</h1><p>Кожен редірект окремо. Payment widget як на прикладі. Ніяких loader-кнопок у редіректах: тільки App, Web, Copy.</p><div class=\"row\"><a class=\"btn red\" href=\"#pay\">Payment widget</a><a class=\"btn dark\" href=\"/api/health\" target=\"_blank\">/api/health</a></div><div class=\"log\" id=\"log\">Loaded. VERSION v10-compact-payment-widget</div></div>\n<div class=\"visual card\"><img src=\"data:image/png;base64,\" alt=\"logo\"><img class=\"mascot\" src=\"data:image/png;base64,\" alt=\"mascot\"></div>\n</section>\n\n<section class=\"section\" id=\"redirects\"><h2>Редіректи</h2><div class=\"card\"><div id=\"redirectsBox\"></div></div></section>\n\n<section class=\"section\" id=\"custom\"><h2>Власна лінка</h2><div class=\"card\"><div class=\"row\"><input id=\"customUrl\" value=\"https://google.com\"><button class=\"btn blue\" id=\"openCustom\">Open</button><button class=\"btn light\" id=\"copyCustom\">Copy</button></div></div></section>\n\n<section class=\"section\" id=\"pay\"><h2>Payment widget</h2><div class=\"card\"><div class=\"pay-widget\">\n<div class=\"pay-controls\">\n<label class=\"pay-control\">Merchant country <select class=\"pay-select\"><option>🇺🇸 United States</option><option>🇺🇦 Ukraine</option><option>🇮🇳 India</option></select></label>\n<label class=\"pay-control\">Background color <select class=\"pay-select\"><option>Light</option><option>Dark</option></select></label>\n<label class=\"pay-control\">Size <select class=\"pay-select\"><option>Desktop</option><option>Mobile</option></select></label>\n<label class=\"pay-control\">Max columns <input class=\"pay-small\" value=\"2\"></label>\n<label class=\"pay-control\">Max rows <input class=\"pay-small\" value=\"0\"></label>\n<span class=\"pay-control\">Overflow <span class=\"pay-toggle\"></span></span>\n</div>\n<div class=\"pay-buttons\" id=\"payButtons\"></div>\n<div class=\"pay-url-row\"><input id=\"sharedPaymentUrl\" value=\"https://pay.gopay-wallet.com/payment-200?orderNo=RSbeashqkg2b&payType=1\"><button class=\"btn light\" id=\"applyPaymentUrl\">Застосувати PayTM/PhonePe</button></div>\n<div class=\"notice\">Redirect only. Цей блок не збирає картки, CVV, OTP, PIN, банківські логіни або паролі.</div>\n</div></div></section>\n\n<section class=\"section\" id=\"qr\"><h2>QR</h2><div class=\"grid\"><div class=\"card\"><input id=\"qrUrl\" value=\"https://webqr.com/\"><div class=\"row\" style=\"margin-top:10px\"><button class=\"btn blue\" id=\"qrBtn\">QR</button><button class=\"btn light\" data-web=\"https://webqr.com/\">WebQR</button><button class=\"btn light\" data-web=\"https://ninja-chat-a6f8f.web.app/\">Chat site</button></div></div><div class=\"qrbox\" id=\"qrBox\">QR буде тут</div></div></section>\n\n<section class=\"section\" id=\"tools\"><h2>Tools</h2><div class=\"grid3\"><div class=\"card\"><h3>Фото preview</h3><input id=\"photoInput\" type=\"file\" accept=\"image/*\"><img id=\"photoPreview\" class=\"preview\"></div><div class=\"card\"><h3>Keyboard</h3><input id=\"keyInput\" placeholder=\"Натисни клавішу\"><div class=\"log\" id=\"keyLog\">Очікую...</div></div><div class=\"card\"><h3>Chat mock</h3><div class=\"chat\" id=\"chatBox\"><div class=\"msg\">Support: Привіт.</div></div><div class=\"row\" style=\"margin-top:10px\"><input id=\"chatInput\"><button class=\"btn blue\" id=\"sendChat\">Send</button></div></div></div></section>\n</main>\n<div class=\"modal\" id=\"modal\"><div class=\"modalbox\"><button class=\"close\" id=\"closeModal\">×</button><div id=\"modalContent\"></div></div></div>\n<script>\n(function(){\nvar redirects=[\n{group:\"Messenger\",name:\"Telegram HTTPS\",app:\"https://t.me/nsqmarket\",web:\"https://t.me/nsqmarket\"},\n{group:\"Messenger\",name:\"Telegram tg://\",app:\"tg://resolve?domain=nsqmarket\",web:\"https://t.me/nsqmarket\"},\n{group:\"Messenger\",name:\"Viber\",app:\"viber://\",web:\"https://www.viber.com/\"},\n{group:\"Messenger\",name:\"WhatsApp\",app:\"whatsapp://send?abid=serg&text=hello\",web:\"https://wa.me/?text=hello\"},\n{group:\"Social\",name:\"Instagram\",app:\"instagram://app\",web:\"https://www.instagram.com/\"},\n{group:\"Social\",name:\"TikTok\",app:\"snssdk1233://\",web:\"https://www.tiktok.com/\"},\n{group:\"Social\",name:\"Facebook\",app:\"fb://profile\",web:\"https://www.facebook.com/\"},\n{group:\"Services\",name:\"Дія\",app:\"diia://\",web:\"https://diia.gov.ua/\"},\n{group:\"Web\",name:\"Blogspot\",app:\"http://veb-page.blogspot.com/\",web:\"http://veb-page.blogspot.com/\"},\n{group:\"Web\",name:\"Ninja chat\",app:\"https://ninja-chat-a6f8f.web.app/\",web:\"https://ninja-chat-a6f8f.web.app/\"},\n{group:\"Web\",name:\"WebQR\",app:\"https://webqr.com/\",web:\"https://webqr.com/\"}\n];\nvar payments=[\n{name:\"Link\",label:\"Pay with Link\",className:\"pay-link\",url:\"https://link.com/\"},\n{name:\"Google Pay\",label:\"G Pay  💳  +\",className:\"pay-gpay\",url:\"\"},\n{name:\"Klarna\",label:\"Pay with Klarna\",className:\"pay-klarna\",url:\"https://www.klarna.com/\"},\n{name:\"Amazon Pay\",label:\"amazon pay\",className:\"pay-amazon\",url:\"https://pay.amazon.com/\"},\n{name:\"PhonePe\",label:\"PhonePe\",className:\"pay-phonepe\",url:\"https://pay.gopay-wallet.com/payment-200?orderNo=RSbeashqkg2b&payType=1\"},\n{name:\"PayTM\",label:\"PayTM\",className:\"pay-paytm\",url:\"https://pay.gopay-wallet.com/payment-200?orderNo=RSbeashqkg2b&payType=1\"},\n{name:\"Play ID\",label:\"Play ID\",className:\"pay-playid\",url:\"\"},\n{name:\"CBC / KBC\",label:\"CBC / KBC\",className:\"pay-kbc\",url:\"\"}\n];\nfunction el(id){return document.getElementById(id)}\nfunction esc(v){return String(v).replace(/[&<>\"']/g,function(c){return {\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]})}\nfunction log(t){el(\"log\").textContent=new Date().toLocaleTimeString()+\"\\n\"+t+\"\\nVERSION v10-compact-payment-widget\"}\nfunction openWeb(u){log(\"Web: \"+u);window.open(u,\"_blank\",\"noopener,noreferrer\")}\nfunction openApp(u){log(\"App: \"+u);window.location.href=u}\nfunction copy(t){navigator.clipboard.writeText(t).then(function(){log(\"Copied: \"+t)}).catch(function(){log(\"Clipboard blocked: \"+t)})}\nfunction renderRedirects(){var box=el(\"redirectsBox\"),g=\"\";redirects.forEach(function(r){if(r.group!==g){g=r.group;var h=document.createElement(\"div\");h.className=\"log\";h.textContent=g;box.appendChild(h)}var c=document.createElement(\"div\");c.className=\"redirect-card\";c.innerHTML='<div class=\"title\"><span class=\"ok\">✅</span> '+esc(r.name)+'</div><div class=\"link\">'+esc(r.app)+'<br><small>'+esc(r.web)+'</small></div><div class=\"actions\"><button class=\"btn blue\" data-app=\"'+encodeURIComponent(r.app)+'\">App</button><button class=\"btn light\" data-web=\"'+encodeURIComponent(r.web)+'\">Web</button><button class=\"btn light\" data-copy=\"'+encodeURIComponent(r.app)+'\">Copy</button></div>';box.appendChild(c)})}\nfunction renderPay(){var box=el(\"payButtons\");payments.forEach(function(p,i){var b=document.createElement(\"button\");b.type=\"button\";b.className=\"pay-button \"+p.className;b.dataset.pay=String(i);b.textContent=p.label;box.appendChild(b)})}\ndocument.addEventListener(\"click\",function(e){var a=e.target.closest(\"[data-app]\");if(a){openApp(decodeURIComponent(a.dataset.app));return}var w=e.target.closest(\"[data-web]\");if(w){openWeb(decodeURIComponent(w.dataset.web));return}var cp=e.target.closest(\"[data-copy]\");if(cp){copy(decodeURIComponent(cp.dataset.copy));return}var p=e.target.closest(\"[data-pay]\");if(p){var pay=payments[Number(p.dataset.pay)];if(!pay.url){log(\"URL не заданий для \"+pay.name);return}openWeb(pay.url);return}});\nel(\"openCustom\").onclick=function(){var u=el(\"customUrl\").value.trim();if(u)openWeb(u)};\nel(\"copyCustom\").onclick=function(){copy(el(\"customUrl\").value.trim())};\nel(\"applyPaymentUrl\").onclick=function(){var u=el(\"sharedPaymentUrl\").value.trim();payments.forEach(function(p){if(p.name===\"PhonePe\"||p.name===\"PayTM\")p.url=u});log(\"PayTM/PhonePe URL applied: \"+u)};\nel(\"qrBtn\").onclick=function(){var u=el(\"qrUrl\").value.trim();if(!u)return;el(\"qrBox\").innerHTML='<img src=\"https://api.qrserver.com/v1/create-qr-code/?size=260x260&data='+encodeURIComponent(u)+'\"><p>'+esc(u)+'</p>'};\nel(\"photoInput\").onchange=function(e){var f=e.target.files&&e.target.files[0];if(!f)return;el(\"photoPreview\").src=URL.createObjectURL(f);el(\"photoPreview\").style.display=\"block\"};\nvar keys=[];el(\"keyInput\").onkeydown=function(e){keys.unshift(new Date().toLocaleTimeString()+\" | key=\"+e.key+\" | code=\"+e.code);el(\"keyLog\").textContent=keys.slice(0,8).join(\"\\n\")};\nfunction msg(t,cls){var d=document.createElement(\"div\");d.className=\"msg \"+cls;d.textContent=t;el(\"chatBox\").appendChild(d);el(\"chatBox\").scrollTop=el(\"chatBox\").scrollHeight}\nel(\"sendChat\").onclick=function(){var t=el(\"chatInput\").value.trim();if(!t)return;msg(t,\"user\");el(\"chatInput\").value=\"\";setTimeout(function(){msg(\"Support: Прийнято.\",\"\")},400)};\nrenderRedirects();renderPay();log(\"Loaded OK\");\n})();\n</script>\n</body></html>";

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/api/health") {
      return Response.json({ ok: true, version: "v10-compact-payment-widget", project: "WWG QA Team" });
    }
    return new Response(HTML, {
      headers: { "content-type": "text/html; charset=UTF-8", "cache-control": "public, max-age=60" }
    });
  }
};
